:root {
  --bg: #1a1c2c;
  --card: #2b2f4a;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --muted: #a0a4c0;
  --btn: #3b3f5c;
  --btn-hover: #4e5378;
  --btn-active: #2a2d45;
  --focus: #ffcd75;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 12px;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 0 rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 1px;
  margin-bottom: 8px;
  color: var(--accent);
}

.subtitle {
  font-size: 1rem;
  color: var(--muted);
  margin-bottom: 24px;
}

.count {
  display: block;
  font-size: 4rem;
  font-weight: 700;
  line-height: 1.2;
  margin: 16px 0 24px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  word-break: break-all;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 600;
  min-width: 64px;
  padding: 12px 20px;
  border: 3px solid var(--accent);
  border-radius: 8px;
  background: var(--btn);
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  box-shadow: 0 4px 0 rgba(0,0,0,0.4);
}

.btn:hover {
  background: var(--btn-hover);
}

.btn:active {
  background: var(--btn-active);
  transform: translateY(2px);
  box-shadow: 0 2px 0 rgba(0,0,0,0.4);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn-reset {
  font-size: 1rem;
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

.btn-reset:hover {
  background: #ffe08a;
}

.btn-reset:active {
  background: #e6b84f;
}

.hint {
  margin-top: 20px;
  font-size: 0.9rem;
  color: var(--muted);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .count {
    font-size: 3rem;
  }
  .btn {
    min-width: 56px;
    padding: 10px 16px;
  }
}

'use strict';

const countEl = document.getElementById('count');
const increaseBtn = document.getElementById('increase');
const decreaseBtn = document.getElementById('decrease');
const resetBtn = document.getElementById('reset');

let count = 0;

function render() {
  countEl.textContent = String(count);
}

increaseBtn.addEventListener('click', () => {
  count += 1;
  render();
});

decreaseBtn.addEventListener('click', () => {
  count -= 1;
  render();
});

resetBtn.addEventListener('click', () => {
  count = 0;
  render();
});

render();
